/* ============ Property Tycoon — base ============ */
:root {
  --ink: #2b2440;
  --ink-soft: #665f7c;
  --cream: #fff8ec;
  --paper: #fffdf8;
  --line: #eadfce;
  --green: #1f9d63;
  --green-soft: #d8f6e5;
  --amber: #b57808;
  --amber-soft: #fff0c2;
  --red: #d63b45;
  --red-soft: #ffe0e1;
  --violet: #7455d6;
  --shadow: 0 14px 30px -16px rgba(52, 37, 78, .35);
  --shadow-soft: 0 8px 20px -12px rgba(52, 37, 78, .28);
  --radius: 22px;
  --font: "Lato", "DejaVu Sans", system-ui, -apple-system, "Segoe UI", sans-serif;
}

* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body {
  margin: 0;
  font-family: var(--font);
  color: var(--ink);
  background:
    radial-gradient(1100px 500px at 10% -10%, #ffe9bd 0%, transparent 55%),
    radial-gradient(1000px 500px at 100% 0%, #d9f4ef 0%, transparent 55%),
    linear-gradient(180deg, #fffaf0 0%, #fdf5e8 55%, #f8efdf 100%);
  min-height: 100vh;
  -webkit-font-smoothing: antialiased;
}
body::before {
  content: "";
  position: fixed;
  inset: 0;
  pointer-events: none;
  opacity: .35;
  background-image: radial-gradient(#e4d6bf 1px, transparent 1px);
  background-size: 26px 26px;
  z-index: 0;
}
button, input, select, textarea { font: inherit; color: inherit; }
button { cursor: pointer; }
h1, h2, h3, h4, p { margin: 0; }
:focus-visible { outline: 3px solid #7455d6; outline-offset: 3px; }

/* ============ app shell ============ */
.app-shell { position: relative; z-index: 1; max-width: 1440px; margin: 0 auto; padding: 0 26px 34px; }

.topbar {
  display: flex;
  align-items: center;
  gap: 24px;
  padding: 20px 4px 14px;
}
.brand { display: flex; align-items: center; gap: 12px; min-width: 238px; }
.brand-mark {
  position: relative;
  width: 54px; height: 54px;
  display: grid; place-items: center;
  background: linear-gradient(150deg, #ffdf8e, #ffbe55);
  border: 3px solid #2b2440;
  border-radius: 17px;
  box-shadow: 0 5px 0 #2b2440;
  transform: rotate(-3deg);
}
.brand-house { font-size: 30px; line-height: 1; transform: rotate(3deg); }
.brand-coin {
  position: absolute; right: -9px; bottom: -9px; font-size: 20px;
  transform: rotate(10deg);
  filter: drop-shadow(0 2px 0 rgba(0,0,0,.2));
}
.brand-copy h1 { font-size: 25px; font-weight: 900; letter-spacing: -.045em; }
.brand-copy p { font-size: 12px; font-weight: 700; text-transform: uppercase; letter-spacing: .13em; color: var(--ink-soft); margin-top: 2px; }

.dashboard { display: flex; gap: 12px; flex: 1; justify-content: center; flex-wrap: wrap; }
.dash-stat {
  display: flex; align-items: center; gap: 10px;
  background: rgba(255, 253, 248, .88);
  border: 1.5px solid var(--line);
  border-radius: 16px;
  padding: 9px 14px 9px 11px;
  min-width: 148px;
  box-shadow: var(--shadow-soft);
}
.dash-stat .dash-icon {
  display: grid; place-items: center;
  width: 34px; height: 34px; border-radius: 11px;
  background: #f1ebff; font-size: 18px; flex: none;
}
.dash-stat.collected .dash-icon { background: var(--green-soft); }
.dash-stat.due .dash-icon { background: var(--amber-soft); }
.dash-stat .dash-copy { display: flex; flex-direction: column; line-height: 1.12; }
.dash-stat .dash-label { font-size: 10px; font-weight: 800; letter-spacing: .09em; text-transform: uppercase; color: var(--ink-soft); }
.dash-stat strong { font-size: 19px; font-weight: 900; letter-spacing: -.03em; font-variant-numeric: tabular-nums; }
.dash-stat.collected strong { color: var(--green); }
.dash-stat.due strong { color: #bf6c00; }

.top-actions { display: flex; gap: 8px; }
.icon-btn {
  width: 42px; height: 42px; border-radius: 13px;
  border: 1.5px solid var(--line); background: var(--paper);
  font-size: 18px; line-height: 1;
  box-shadow: 0 3px 0 #e2d5c2;
  transition: transform .12s, box-shadow .12s;
}
.icon-btn:hover { transform: translateY(-1px); box-shadow: 0 4px 0 #e2d5c2; }
.icon-btn:active { transform: translateY(2px); box-shadow: 0 1px 0 #e2d5c2; }
.icon-btn.muted { opacity: .55; }

/* ============ control bar ============ */
.controlbar {
  display: flex; align-items: center; gap: 14px;
  padding: 10px 12px;
  background: rgba(255, 253, 248, .8);
  border: 1.5px solid var(--line);
  border-radius: 18px;
  backdrop-filter: blur(12px);
  position: sticky; top: 8px; z-index: 30;
  box-shadow: 0 8px 26px -18px rgba(52, 37, 78, .4);
}
.tabs { display: flex; gap: 4px; padding: 4px; background: #f4ecdf; border-radius: 13px; }
.tab {
  display: flex; align-items: center; gap: 6px;
  border: 0; background: transparent; color: var(--ink-soft);
  font-size: 13px; font-weight: 800;
  padding: 8px 12px; border-radius: 10px;
  transition: background .15s, color .15s, box-shadow .15s;
}
.tab:hover { color: var(--ink); }
.tab.active { background: var(--paper); color: var(--ink); box-shadow: 0 2px 8px rgba(52,37,78,.12); }
.month-chip {
  display: flex; align-items: center; gap: 7px;
  font-weight: 900; font-size: 14px; white-space: nowrap;
  padding-left: 4px;
}
.month-chip small { display: block; font-size: 9px; letter-spacing: .12em; color: var(--ink-soft); font-weight: 800; }
.xp-wrap { display: flex; align-items: center; gap: 9px; flex: 1; min-width: 140px; max-width: 300px; }
.xp-badge {
  flex: none; font-size: 11px; font-weight: 900;
  background: #2b2440; color: #ffe8a3;
  border-radius: 9px; padding: 5px 7px; line-height: 1;
  letter-spacing: .02em;
}
.xp-body { flex: 1; min-width: 0; }
.xp-top { display: flex; justify-content: space-between; gap: 8px; font-size: 9.5px; font-weight: 800; color: var(--ink-soft); letter-spacing: .04em; margin-bottom: 4px; }
.xp-top b { color: var(--ink); }
.xp-track { height: 8px; background: #efe4d3; border-radius: 99px; overflow: hidden; box-shadow: inset 0 1px 2px rgba(52,37,78,.12); }
.xp-fill {
  height: 100%; border-radius: inherit;
  background: linear-gradient(90deg, #8a6bf2, #ff9d5c, #ffd45e);
  background-size: 200% 100%;
  animation: xpShimmer 3s linear infinite;
  transition: width .6s cubic-bezier(.2,.8,.2,1);
}
@keyframes xpShimmer { to { background-position: 200% 0; } }

.primary-actions { display: flex; gap: 8px; margin-left: auto; }
.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 7px;
  border-radius: 13px; border: 1.5px solid transparent;
  font-size: 13px; font-weight: 900; letter-spacing: -.01em;
  padding: 10px 14px; white-space: nowrap;
  transition: transform .12s, box-shadow .12s, filter .12s;
}
.btn:hover { transform: translateY(-1px); }
.btn:active { transform: translateY(1px); }
.btn-primary {
  background: #2b2440; color: #fff9ec;
  border-color: #2b2440; box-shadow: 0 4px 0 #120d22, 0 10px 20px -10px rgba(43,36,64,.6);
}
.btn-primary:hover { background: #3a3157; }
.btn-collect {
  background: linear-gradient(145deg, #ffd86b, #ffb52e);
  color: #4b2c00; border-color: #d99312;
  box-shadow: 0 4px 0 #d99312;
}
.btn-collect:hover { filter: brightness(1.04); }
.btn-collect.active { background: linear-gradient(145deg, #9df0bf, #4ad687); border-color: #1f9d63; box-shadow: 0 4px 0 #1f9d63; color: #094b2c; }
.btn-advance {
  background: linear-gradient(145deg, #8f75f5, #7054d8);
  color: white; border-color: #5a40bd;
  box-shadow: 0 4px 0 #5a40bd;
}
.btn-soft {
  background: var(--paper); border-color: var(--line); color: var(--ink);
  box-shadow: 0 3px 0 #e5d8c6;
}
.btn-soft:hover { background: #fffaf1; }
.btn-danger { background: #e5484f; border-color: #c52f37; color: #fff; box-shadow: 0 4px 0 #b3272f; }
.btn-sm { padding: 7px 11px; font-size: 12px; border-radius: 10px; }
.btn[disabled] { opacity: .45; pointer-events: none; }
.link-btn {
  border: 0; background: none; padding: 0; color: var(--violet);
  font-weight: 900; font-size: inherit; text-decoration: underline; text-underline-offset: 3px;
}

/* ============ banners ============ */
#banner-slot { display: flex; flex-direction: column; gap: 8px; }
.notice {
  display: flex; align-items: center; gap: 12px;
  margin-top: 14px; padding: 11px 14px;
  border-radius: 15px; border: 1.5px dashed #d9c7af;
  background: rgba(255, 251, 241, .9);
  font-size: 13px; font-weight: 600; color: var(--ink-soft);
}
.notice b { color: var(--ink); }
.notice .notice-icon { font-size: 20px; }
.notice .notice-actions { margin-left: auto; display: flex; gap: 8px; flex: none; }
.notice-close { border: 0; background: transparent; font-size: 16px; opacity: .6; padding: 4px; }
.collection-banner {
  display: flex; align-items: center; gap: 13px; flex-wrap: wrap;
  margin-top: 14px; padding: 12px 16px;
  border-radius: 16px; border: 2px solid #e0a51b;
  background: linear-gradient(100deg, #fff4c9, #ffe49a);
  box-shadow: 0 8px 24px -16px rgba(180, 120, 0, .7);
  animation: bannerDrop .4s cubic-bezier(.2,.9,.3,1.2);
}
.collection-banner .banner-emoji { font-size: 27px; animation: coinBob 1.6s ease-in-out infinite; }
.collection-banner .banner-copy { font-size: 13px; font-weight: 700; }
.collection-banner .banner-copy strong { display: block; font-size: 15px; font-weight: 900; }
.collection-banner .banner-progress { margin-left: auto; display: flex; align-items: center; gap: 10px; }
.mini-track { width: 110px; height: 9px; border-radius: 99px; background: rgba(255,255,255,.7); overflow: hidden; }
.mini-track span { display: block; height: 100%; border-radius: inherit; background: linear-gradient(90deg, #ffae2b, #ff7a3d); transition: width .5s; }
@keyframes bannerDrop { from { opacity: 0; transform: translateY(-8px); } }

/* ============ main / shared ============ */
main { padding-top: 20px; min-height: 60vh; }
.page-kicker { font-size: 11px; font-weight: 900; letter-spacing: .16em; text-transform: uppercase; color: var(--violet); display: flex; align-items: center; gap: 7px; }
.page-kicker::before { content: ""; width: 18px; height: 3px; border-radius: 9px; background: currentColor; }
.page-title { font-size: clamp(28px, 3.2vw, 40px); font-weight: 900; letter-spacing: -.045em; line-height: 1.05; margin-top: 6px; }
.page-sub { color: var(--ink-soft); font-size: 14px; font-weight: 600; margin-top: 7px; max-width: 610px; }
.map-hero { display: flex; align-items: flex-end; justify-content: space-between; gap: 22px; margin-bottom: 22px; }
.hero-actions { display: flex; gap: 9px; flex: none; flex-wrap: wrap; }
.hero-card {
  display: flex; align-items: center; gap: 10px;
  background: rgba(255,253,248,.8); border: 1.5px solid var(--line);
  border-radius: 15px; padding: 9px 13px; font-size: 12px; font-weight: 800;
  box-shadow: var(--shadow-soft);
}
.hero-card .hero-num { font-size: 18px; font-weight: 900; }
.hero-card .hero-sub { color: var(--ink-soft); font-size: 10px; text-transform: uppercase; letter-spacing: .08em; }

/* ============ neighborhood map ============ */
.neighborhood {
  position: relative;
  border-radius: 30px;
  border: 2px solid #e8d9c4;
  padding: 26px 24px 54px;
  background:
    radial-gradient(500px 160px at 20% 8%, rgba(255,255,255,.9), transparent 70%),
    linear-gradient(180deg, #dff4ff 0%, #eaf9f5 52%, #f6f1df 53%, #e7f2cf 100%);
  box-shadow: var(--shadow), inset 0 1px 0 #fff;
  overflow: hidden;
}
.neighborhood::before {
  content: "";
  position: absolute; left: 0; right: 0; bottom: 0; height: 74px;
  background:
    repeating-linear-gradient(90deg, transparent 0 54px, rgba(160, 190, 120, .35) 54px 58px, transparent 58px 112px),
    linear-gradient(180deg, #d8eeae, #bfe18d);
  border-top: 3px solid #b5d383;
}
.sun { position: absolute; top: 24px; right: 34px; font-size: 46px; filter: drop-shadow(0 5px 12px rgba(255, 190, 60, .45)); animation: sunPulse 6s ease-in-out infinite; }
@keyframes sunPulse { 50% { transform: scale(1.06) rotate(5deg); } }
.cloud { position: absolute; font-size: 44px; opacity: .8; filter: drop-shadow(0 6px 8px rgba(90, 140, 180, .12)); animation: cloudDrift 28s linear infinite; }
.cloud.c1 { top: 34px; left: 8%; animation-delay: -9s; }
.cloud.c2 { top: 18px; left: 58%; font-size: 32px; animation-delay: -20s; }
@keyframes cloudDrift { 0%,100% { transform: translateX(-10px); } 50% { transform: translateX(26px); } }
.map-road {
  position: absolute; bottom: 18px; left: 0; right: 0; height: 38px;
  background: #b7ad9a; border-top: 3px dashed #fff8df; border-bottom: 3px dashed #fff8df;
  opacity: .8;
}
.map-road::after {
  content: ""; position: absolute; left: 0; right: 0; top: 50%; height: 3px;
  background: repeating-linear-gradient(90deg, #fff4c9 0 30px, transparent 30px 58px);
  transform: translateY(-50%);
}
.map-deco { position: absolute; bottom: 46px; font-size: 32px; z-index: 1; }
.map-deco.tree1 { left: 14px; }
.map-deco.tree2 { right: 16px; font-size: 40px; }
.buildings-grid {
  position: relative; z-index: 2;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(255px, 1fr));
  gap: 20px;
  align-items: stretch;
}
.buildings-grid .add-card { min-height: 340px; }

.bcard {
  position: relative;
  display: flex; flex-direction: column;
  background: var(--paper);
  border: 2px solid #352c4e;
  border-radius: 22px;
  overflow: hidden;
  cursor: pointer;
  box-shadow: 0 6px 0 #352c4e, 0 18px 30px -18px rgba(43,36,64,.55);
  transition: transform .18s cubic-bezier(.2,.8,.3,1.2), box-shadow .18s;
}
.bcard:hover { transform: translateY(-5px) rotate(-.4deg); box-shadow: 0 10px 0 #352c4e, 0 26px 38px -20px rgba(43,36,64,.55); }
.bcard:active { transform: translateY(-1px); }
.bcard-sky {
  position: relative;
  height: 210px;
  display: flex; align-items: flex-end; justify-content: center;
  background:
    radial-gradient(120px 60px at 80% 24%, rgba(255,255,255,.8), transparent 70%),
    linear-gradient(180deg, var(--b-sky, #d8f3ff), var(--b-sky2, #eefbf5));
  overflow: hidden;
  border-bottom: 2px solid #352c4e;
}
.bcard-sky::after {
  content: ""; position: absolute; left: 0; right: 0; bottom: 0; height: 20px;
  background: var(--b-grass, #b4df86);
  border-top: 2px solid rgba(53,44,78,.4);
}
.bcard-actions { position: absolute; top: 10px; right: 10px; display: flex; gap: 5px; z-index: 5; }
.bcard-actions .icon-btn { width: 30px; height: 30px; font-size: 13px; border-radius: 9px; box-shadow: 0 2px 0 #d6c8b4; background: rgba(255,253,248,.92); }
.bcard-emoji-badge {
  position: absolute; top: 10px; left: 10px; z-index: 4;
  background: rgba(255,253,248,.9); border: 1.5px solid rgba(53,44,78,.25);
  border-radius: 10px; padding: 4px 8px; font-size: 10px; font-weight: 900;
  letter-spacing: .05em; text-transform: uppercase; color: var(--ink-soft);
}
.tower { position: relative; width: 150px; margin-bottom: 14px; filter: drop-shadow(0 8px 8px rgba(43,36,64,.18)); }
.tower-roof {
  position: relative; height: 26px; margin: 0 -6px;
  background: var(--b-dark, #d9564f);
  border: 2.5px solid #352c4e;
  border-radius: 8px 8px 3px 3px;
  transform: perspective(90px) rotateX(12deg);
}
.tower-roof::after {
  content: ""; position: absolute; top: 50%; left: -8px; right: -8px; height: 5px;
  background: var(--b, #f9776f); border: 2px solid #352c4e; border-radius: 9px;
  transform: translateY(-50%);
}
.tower-flag { position: absolute; top: -23px; left: 50%; font-size: 18px; transform: translateX(-50%); }
.tower-body {
  display: grid; grid-template-columns: 1fr 1fr; gap: 5px;
  padding: 9px 10px 8px;
  background: var(--b, #f9776f);
  border: 2.5px solid #352c4e;
  border-top: 0;
  border-radius: 0 0 5px 5px;
  position: relative;
}
.tower-body::before, .tower-body::after {
  content: ""; position: absolute; top: 0; bottom: 0; width: 4px;
  background: rgba(53,44,78,.18);
}
.tower-body::before { left: 6px; } .tower-body::after { right: 6px; }
.win {
  position: relative; aspect-ratio: 1.25;
  border-radius: 4px; border: 1.8px solid #352c4e;
  background: #ffe9a9;
  display: grid; place-items: center;
  overflow: hidden;
  font-size: 16px; line-height: 1;
  box-shadow: inset 0 0 0 1.5px rgba(255,255,255,.5);
}
.win.vacant { background: #cdd9e5; }
.win.clear { background: #c9f7dc; }
.win.partial { background: #ffe9a5; }
.win.overdue { background: #ffb9b4; }
.win .win-tenant { filter: drop-shadow(0 1px 0 rgba(0,0,0,.15)); }
.win .win-person { position: absolute; bottom: -1px; font-size: 14px; }
.win .coin-mini {
  position: absolute; top: -3px; right: -3px; z-index: 4;
  width: 24px; height: 24px; border-radius: 50%;
  border: 1.5px solid #a96d00; background: radial-gradient(circle at 35% 30%, #fff1a8, #ffc93c);
  font-size: 12px; display: grid; place-items: center; padding: 0;
  box-shadow: 0 2px 0 #b87800;
  animation: coinBob .9s ease-in-out infinite;
}
.win .coin-mini:hover { transform: scale(1.15); }
@keyframes coinBob { 0%,100% { transform: translateY(0) rotate(-5deg); } 50% { transform: translateY(-4px) rotate(5deg); } }
.tower-entry {
  height: 27px; margin: 0 24px 6px;
  border: 2.5px solid #352c4e; border-top: 0; border-radius: 0 0 7px 7px;
  background: linear-gradient(90deg, var(--b-dark), var(--b));
  position: relative;
}
.tower-entry::before {
  content: ""; position: absolute; left: 50%; top: 0; width: 24px; height: 22px;
  transform: translateX(-50%); background: #5a4838; border: 2px solid #352c4e; border-top: 0; border-radius: 0 0 5px 5px;
}
.tower-entry::after {
  content: "•••"; position: absolute; left: 50%; top: 0; transform: translateX(-50%);
  color: #ffe9a9; font-size: 7px; letter-spacing: 1px;
}
.bcard-body { padding: 14px 16px 16px; flex: 1; display: flex; flex-direction: column; gap: 9px; }
.bcard-title-row { display: flex; align-items: center; gap: 8px; }
.bcard-title { font-size: 19px; font-weight: 900; letter-spacing: -.03em; line-height: 1.1; flex: 1; }
.bcard-arrow { font-size: 15px; opacity: .35; transition: transform .16s, opacity .16s; }
.bcard:hover .bcard-arrow { transform: translateX(3px); opacity: 1; }
.bcard-sub { font-size: 11px; font-weight: 700; color: var(--ink-soft); }
.bcard-badges { display: flex; gap: 7px; flex-wrap: wrap; }
.sum-badge {
  display: inline-flex; align-items: center; gap: 5px;
  border-radius: 9px; padding: 6px 8px;
  font-size: 12px; font-weight: 900; font-variant-numeric: tabular-nums;
  border: 1.5px solid transparent;
}
.sum-badge small { font-size: 8.5px; letter-spacing: .06em; text-transform: uppercase; font-weight: 900; opacity: .7; }
.sum-badge.collected { background: var(--green-soft); color: var(--green); border-color: #b1e8ca; }
.sum-badge.due { background: var(--amber-soft); color: #9c6100; border-color: #f2d693; }
.sum-badge.credit { background: #e9f2ff; color: #2f6fb3; border-color: #c3dcf8; }
.collect-quick { margin-top: auto; }
.collect-quick .btn { width: 100%; }

.add-card {
  display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 10px;
  border: 2.5px dashed #a9987e; border-radius: 22px;
  background: rgba(255, 253, 248, .48);
  color: var(--ink-soft); font-weight: 800; font-size: 14px;
  transition: background .16s, transform .16s, border-color .16s;
}
.add-card:hover { background: rgba(255,253,248,.85); border-color: #7455d6; color: var(--violet); transform: translateY(-3px); }
.add-card .plus-circle {
  width: 56px; height: 56px; border-radius: 50%;
  display: grid; place-items: center;
  background: #fff; border: 2px solid #cbbca5; font-size: 28px; font-weight: 600;
  box-shadow: 0 5px 0 #e3d6c2;
}
.add-card small { font-size: 11px; font-weight: 600; opacity: .8; }

/* ============ building detail ============ */
.building-head { display: flex; align-items: flex-start; gap: 14px; flex-wrap: wrap; margin-bottom: 20px; }
.building-title-group { flex: 1; min-width: 220px; }
.back-btn {
  display: inline-flex; align-items: center; gap: 6px;
  border: 0; background: none; padding: 0; margin-bottom: 10px;
  font-size: 12px; font-weight: 900; color: var(--violet); letter-spacing: .02em;
}
.back-btn:hover { text-decoration: underline; text-underline-offset: 3px; }
.building-name-row { display: flex; align-items: center; gap: 11px; flex-wrap: wrap; }
.building-badge-icon {
  width: 44px; height: 44px; border-radius: 14px;
  display: grid; place-items: center; font-size: 23px;
  background: var(--b-light, #ffe1dc); border: 2px solid var(--b-dark, #d9564f);
  box-shadow: 0 3px 0 var(--b-dark, #d9564f);
  transform: rotate(-3deg);
}
.building-name { font-size: clamp(28px, 3vw, 38px); font-weight: 900; letter-spacing: -.045em; line-height: 1; }
.building-meta { font-size: 12px; font-weight: 700; color: var(--ink-soft); margin-top: 6px; display: flex; gap: 8px; flex-wrap: wrap; align-items: center; }
.building-actions { display: flex; gap: 8px; flex-wrap: wrap; }
.b-summary { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 12px; margin-bottom: 20px; }
.b-stat {
  background: var(--paper); border: 1.5px solid var(--line); border-radius: 16px;
  padding: 12px 14px; box-shadow: var(--shadow-soft); position: relative; overflow: hidden;
}
.b-stat .b-stat-label { display: flex; align-items: center; gap: 6px; font-size: 9.5px; font-weight: 900; letter-spacing: .1em; text-transform: uppercase; color: var(--ink-soft); }
.b-stat strong { display: block; font-size: 23px; font-weight: 900; letter-spacing: -.035em; margin-top: 5px; font-variant-numeric: tabular-nums; }
.b-stat.green strong { color: var(--green); }
.b-stat.amber strong { color: #b06a00; }
.b-stat.violet strong { color: var(--violet); }
.b-stat .b-stat-note { font-size: 10px; font-weight: 700; color: var(--ink-soft); margin-top: 2px; }

.building-layout { display: grid; grid-template-columns: minmax(0, 1fr) 330px; gap: 20px; align-items: start; }
.cutaway {
  position: relative;
  border: 2px solid #352c4e;
  border-radius: 24px;
  overflow: hidden;
  background: linear-gradient(180deg, #dff4ff, #eef9f2);
  box-shadow: 0 8px 0 #352c4e, var(--shadow);
}
.cutaway-roof {
  height: 52px;
  background: var(--b-dark, #d9564f);
  border-bottom: 2.5px solid #352c4e;
  position: relative;
  clip-path: polygon(0 100%, 8% 18%, 50% 0, 92% 18%, 100% 100%);
}
.cutaway-roof::after {
  content: ""; position: absolute; left: 50%; top: 0; bottom: 0; width: 2px;
  background: rgba(53,44,78,.22);
}
.cutaway-sign {
  position: absolute; top: 12px; left: 50%; transform: translateX(-50%) rotate(-1.5deg);
  z-index: 3; background: #fff8df; border: 2px solid #352c4e; border-radius: 8px;
  padding: 3px 14px; font-size: 12px; font-weight: 900; letter-spacing: .03em;
  box-shadow: 0 3px 0 #352c4e; max-width: 70%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.floors { padding: 16px 16px 8px; display: flex; flex-direction: column; gap: 8px; }
.floor-row { display: flex; align-items: stretch; gap: 8px; }
.floor-tag {
  flex: none; width: 30px; display: flex; align-items: center; justify-content: center;
  writing-mode: vertical-rl; transform: rotate(180deg);
  font-size: 9px; font-weight: 900; letter-spacing: .12em; color: rgba(53,44,78,.5);
  background: repeating-linear-gradient(180deg, transparent 0 6px, rgba(53,44,78,.12) 6px 7px);
  border-radius: 7px;
}
.floor-units {
  flex: 1; display: grid; grid-template-columns: repeat(var(--units, 2), minmax(0, 1fr)); gap: 8px;
  background:
    repeating-linear-gradient(90deg, rgba(255,255,255,.25) 0 2px, transparent 2px 28px),
    var(--b-light, #ffe1dc);
  border: 1.5px solid rgba(53,44,78,.35);
  border-radius: 10px; padding: 8px;
}
.unit {
  position: relative;
  background: rgba(255,253,248,.94);
  border: 1.5px solid #cfc3b3;
  border-radius: 11px;
  padding: 7px;
  cursor: pointer;
  min-height: 126px;
  display: flex; flex-direction: column; align-items: stretch;
  transition: transform .14s, box-shadow .14s, border-color .14s;
}
.unit:hover { transform: translateY(-2px); border-color: #7455d6; box-shadow: 0 8px 16px -10px rgba(60,40,90,.5); }
.unit.vacant { border-style: dashed; background: rgba(255,253,248,.55); align-items: center; justify-content: center; text-align: center; color: var(--ink-soft); }
.unit.vacant:hover { border-color: #1f9d63; }
.unit-window {
  position: relative; height: 42px; border: 1.5px solid #352c4e;
  border-radius: 6px; background: linear-gradient(180deg, #ffeeb2, #fff8dd);
  display: grid; place-items: center; overflow: hidden;
  box-shadow: inset 0 -4px 0 rgba(53,44,78,.1);
}
.unit-window::before, .unit-window::after {
  content: ""; position: absolute; background: rgba(53,44,78,.25);
}
.unit-window::before { left: 50%; top: 0; bottom: 0; width: 1.5px; }
.unit-window::after { top: 50%; left: 0; right: 0; height: 1.5px; }
.unit-window .t-emoji { position: relative; z-index: 2; font-size: 22px; transform: translateY(2px); filter: drop-shadow(0 1px 0 rgba(0,0,0,.18)); }
.unit-window .mood {
  position: absolute; z-index: 3; top: -3px; right: 1px; font-size: 13px;
  filter: drop-shadow(0 1px 0 #fff);
  animation: moodFloat 2.8s ease-in-out infinite;
}
@keyframes moodFloat { 50% { transform: translateY(-3px) rotate(4deg); } }
.unit-window .coin-btn {
  position: absolute; z-index: 6; left: 50%; top: 50%;
  transform: translate(-50%, -50%);
  width: 38px; height: 38px; border-radius: 50%;
  border: 2px solid #a96d00;
  background: radial-gradient(circle at 35% 30%, #fff5b8, #ffc93c 65%, #eaa400);
  color: #6b4200; font-size: 9px; font-weight: 900;
  display: flex; flex-direction: column; align-items: center; justify-content: center; line-height: .95;
  box-shadow: 0 3px 0 #a96d00, 0 0 0 3px rgba(255,220,100,.45);
  animation: coinBob 1s ease-in-out infinite;
}
.unit-window .coin-btn:hover { filter: brightness(1.07); transform: translate(-50%, -53%) scale(1.08); }
.unit-window .coin-btn span { font-size: 7px; }
.door-row { display: flex; align-items: flex-end; gap: 6px; margin-top: 6px; }
.door {
  width: 27px; height: 34px; border: 1.5px solid #352c4e; border-radius: 5px 5px 2px 2px;
  position: relative; flex: none; transition: filter .15s;
  background: #c7cbd6;
}
.door::before {
  content: ""; position: absolute; left: 2px; right: 2px; top: 2px; height: 9px;
  background: rgba(255,255,255,.4); border-radius: 2px;
}
.door::after {
  content: ""; position: absolute; right: 4px; top: 18px; width: 3px; height: 3px;
  border-radius: 50%; background: #4d432f;
}
.door.clear { background: linear-gradient(180deg, #7fe7a6, #35b86b); }
.door.partial { background: linear-gradient(180deg, #ffe47c, #f2bb26); }
.door.overdue { background: linear-gradient(180deg, #ff8f8a, #e5454d); }
.door.vacant { background: repeating-linear-gradient(45deg, #d8d4cc 0 5px, #c6c1b8 5px 10px); }
.unit-label { font-size: 11px; font-weight: 900; letter-spacing: .03em; margin-bottom: 2px; }
.unit-name { font-size: 10px; font-weight: 800; color: var(--ink-soft); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; line-height: 1.2; }
.unit-balance { font-size: 9.5px; font-weight: 900; margin-top: 3px; font-variant-numeric: tabular-nums; }
.unit-balance.clear { color: var(--green); }
.unit-balance.partial { color: #a96a00; }
.unit-balance.overdue { color: var(--red); }
.unit-rent { font-size: 9px; font-weight: 700; color: var(--ink-soft); opacity: .8; margin-top: 1px; }
.vacant-plus {
  width: 29px; height: 29px; border-radius: 50%; display: grid; place-items: center;
  border: 1.5px dashed #a9987e; font-size: 18px; color: var(--ink-soft); margin-bottom: 5px;
}
.unit.vacant .v-label { font-size: 10px; font-weight: 900; }
.unit.vacant .v-sub { font-size: 8.5px; font-weight: 700; opacity: .7; margin-top: 2px; }
.cutaway-ground {
  height: 42px; display: flex; align-items: flex-end; justify-content: space-around;
  background: linear-gradient(180deg, #cfe7a3, #b7d98a);
  border-top: 2px solid rgba(53,44,78,.35); position: relative; padding-bottom: 4px;
}
.cutaway-ground .ground-deco { font-size: 21px; }
.legend { display: flex; align-items: center; gap: 15px; flex-wrap: wrap; padding: 13px 16px; font-size: 10.5px; font-weight: 800; color: var(--ink-soft); }
.legend span { display: inline-flex; align-items: center; gap: 5px; }
.legend i { width: 10px; height: 10px; border-radius: 3px; display: inline-block; border: 1px solid rgba(53,44,78,.3); }
.legend .g { background: #45c97c; } .legend .y { background: #f5c32d; } .legend .r { background: #ef5b60; }
.cutaway-footer { background: rgba(255,253,248,.75); border-top: 1.5px solid #e4d8c7; }

.roster {
  background: var(--paper); border: 1.5px solid var(--line); border-radius: 20px;
  box-shadow: var(--shadow-soft); overflow: hidden;
  position: sticky; top: 92px;
}
.roster-head { display: flex; align-items: center; gap: 8px; padding: 15px 15px 11px; border-bottom: 1px solid var(--line); }
.roster-head h3 { flex: 1; font-size: 15px; font-weight: 900; }
.roster-head .count-pill { font-size: 10px; font-weight: 900; padding: 3px 7px; border-radius: 99px; background: #f1ebff; color: var(--violet); }
.roster-list { max-height: 470px; overflow-y: auto; padding: 7px; display: flex; flex-direction: column; gap: 2px; }
.roster-row {
  display: flex; align-items: center; gap: 9px; width: 100%;
  border: 0; background: transparent; border-radius: 12px;
  padding: 8px; text-align: left;
  transition: background .13s;
}
.roster-row:hover { background: #faf4e9; }
.avatar {
  width: 35px; height: 35px; border-radius: 11px; flex: none;
  display: grid; place-items: center; font-size: 19px;
  background: linear-gradient(160deg, #fff1c4, #ffd984);
  border: 1.5px solid #e3c67d;
}
.avatar.g { background: linear-gradient(160deg, #d9fbe7, #a4edc1); border-color: #7fd8a3; }
.avatar.y { background: linear-gradient(160deg, #fff2bf, #ffda77); border-color: #e8c45c; }
.avatar.r { background: linear-gradient(160deg, #ffe0de, #ffb3ae); border-color: #ef8c86; }
.roster-copy { flex: 1; min-width: 0; }
.roster-name { display: block; font-size: 12px; font-weight: 900; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.roster-sub { display: block; font-size: 9.5px; font-weight: 700; color: var(--ink-soft); }
.roster-balance { text-align: right; flex: none; }
.roster-balance b { display: block; font-size: 11px; font-weight: 900; font-variant-numeric: tabular-nums; }
.roster-balance span { font-size: 8px; font-weight: 800; letter-spacing: .05em; text-transform: uppercase; opacity: .6; }
.roster-balance.clear b { color: var(--green); }
.roster-balance.partial b { color: #a96a00; }
.roster-balance.overdue b { color: var(--red); }
.roster-footer { padding: 10px; border-top: 1px solid var(--line); }
.roster-footer .btn { width: 100%; }
.empty-roster { padding: 24px 14px; text-align: center; font-size: 12px; color: var(--ink-soft); font-weight: 600; }

/* ============ Property Tycoon — base ============ */
:root {
  --ink: #2b2440;
  --ink-soft: #665f7c;
  --cream: #fff8ec;
  --paper: #fffdf8;
  --line: #eadfce;
  --green: #1f9d63;
  --green-soft: #d8f6e5;
  --amber: #b57808;
  --amber-soft: #fff0c2;
  --red: #d63b45;
  --red-soft: #ffe0e1;
  --violet: #7455d6;
  --shadow: 0 14px 30px -16px rgba(52, 37, 78, .35);
  --shadow-soft: 0 8px 20px -12px rgba(52, 37, 78, .28);
  --radius: 22px;
  --font: "Lato", "DejaVu Sans", system-ui, -apple-system, "Segoe UI", sans-serif;
}

* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body {
  margin: 0;
  font-family: var(--font);
  color: var(--ink);
  background:
    radial-gradient(1100px 500px at 10% -10%, #ffe9bd 0%, transparent 55%),
    radial-gradient(1000px 500px at 100% 0%, #d9f4ef 0%, transparent 55%),
    linear-gradient(180deg, #fffaf0 0%, #fdf5e8 55%, #f8efdf 100%);
  min-height: 100vh;
  -webkit-font-smoothing: antialiased;
}
body::before {
  content: "";
  position: fixed;
  inset: 0;
  pointer-events: none;
  opacity: .35;
  background-image: radial-gradient(#e4d6bf 1px, transparent 1px);
  background-size: 26px 26px;
  z-index: 0;
}
button, input, select, textarea { font: inherit; color: inherit; }
button { cursor: pointer; }
h1, h2, h3, h4, p { margin: 0; }
:focus-visible { outline: 3px solid #7455d6; outline-offset: 3px; }

/* ============ app shell ============ */
.app-shell { position: relative; z-index: 1; max-width: 1440px; margin: 0 auto; padding: 0 26px 34px; }

.topbar {
  display: flex;
  align-items: center;
  gap: 24px;
  padding: 20px 4px 14px;
}
.brand { display: flex; align-items: center; gap: 12px; min-width: 238px; }
.brand-mark {
  position: relative;
  width: 54px; height: 54px;
  display: grid; place-items: center;
  background: linear-gradient(150deg, #ffdf8e, #ffbe55);
  border: 3px solid #2b2440;
  border-radius: 17px;
  box-shadow: 0 5px 0 #2b2440;
  transform: rotate(-3deg);
}
.brand-house { font-size: 30px; line-height: 1; transform: rotate(3deg); }
.brand-coin {
  position: absolute; right: -9px; bottom: -9px; font-size: 20px;
  transform: rotate(10deg);
  filter: drop-shadow(0 2px 0 rgba(0,0,0,.2));
}
.brand-copy h1 { font-size: 25px; font-weight: 900; letter-spacing: -.045em; }
.brand-copy p { font-size: 12px; font-weight: 700; text-transform: uppercase; letter-spacing: .13em; color: var(--ink-soft); margin-top: 2px; }

.dashboard { display: flex; gap: 12px; flex: 1; justify-content: center; flex-wrap: wrap; }
.dash-stat {
  display: flex; align-items: center; gap: 10px;
  background: rgba(255, 253, 248, .88);
  border: 1.5px solid var(--line);
  border-radius: 16px;
  padding: 9px 14px 9px 11px;
  min-width: 148px;
  box-shadow: var(--shadow-soft);
}
.dash-stat .dash-icon {
  display: grid; place-items: center;
  width: 34px; height: 34px; border-radius: 11px;
  background: #f1ebff; font-size: 18px; flex: none;
}
.dash-stat.collected .dash-icon { background: var(--green-soft); }
.dash-stat.due .dash-icon { background: var(--amber-soft); }
.dash-stat .dash-copy { display: flex; flex-direction: column; line-height: 1.12; }
.dash-stat .dash-label { font-size: 10px; font-weight: 800; letter-spacing: .09em; text-transform: uppercase; color: var(--ink-soft); }
.dash-stat strong { font-size: 19px; font-weight: 900; letter-spacing: -.03em; font-variant-numeric: tabular-nums; }
.dash-stat.collected strong { color: var(--green); }
.dash-stat.due strong { color: #bf6c00; }

.top-actions { display: flex; gap: 8px; }
.icon-btn {
  width: 42px; height: 42px; border-radius: 13px;
  border: 1.5px solid var(--line); background: var(--paper);
  font-size: 18px; line-height: 1;
  box-shadow: 0 3px 0 #e2d5c2;
  transition: transform .12s, box-shadow .12s;
}
.icon-btn:hover { transform: translateY(-1px); box-shadow: 0 4px 0 #e2d5c2; }
.icon-btn:active { transform: translateY(2px); box-shadow: 0 1px 0 #e2d5c2; }
.icon-btn.muted { opacity: .55; }

/* ============ control bar ============ */
.controlbar {
  display: flex; align-items: center; gap: 14px;
  padding: 10px 12px;
  background: rgba(255, 253, 248, .8);
  border: 1.5px solid var(--line);
  border-radius: 18px;
  backdrop-filter: blur(12px);
  position: sticky; top: 8px; z-index: 30;
  box-shadow: 0 8px 26px -18px rgba(52, 37, 78, .4);
}
.tabs { display: flex; gap: 4px; padding: 4px; background: #f4ecdf; border-radius: 13px; }
.tab {
  display: flex; align-items: center; gap: 6px;
  border: 0; background: transparent; color: var(--ink-soft);
  font-size: 13px; font-weight: 800;
  padding: 8px 12px; border-radius: 10px;
  transition: background .15s, color .15s, box-shadow .15s;
}
.tab:hover { color: var(--ink); }
.tab.active { background: var(--paper); color: var(--ink); box-shadow: 0 2px 8px rgba(52,37,78,.12); }
.month-chip {
  display: flex; align-items: center; gap: 7px;
  font-weight: 900; font-size: 14px; white-space: nowrap;
  padding-left: 4px;
}
.month-chip small { display: block; font-size: 9px; letter-spacing: .12em; color: var(--ink-soft); font-weight: 800; }
.xp-wrap { display: flex; align-items: center; gap: 9px; flex: 1; min-width: 140px; max-width: 300px; }
.xp-badge {
  flex: none; font-size: 11px; font-weight: 900;
  background: #2b2440; color: #ffe8a3;
  border-radius: 9px; padding: 5px 7px; line-height: 1;
  letter-spacing: .02em;
}
.xp-body { flex: 1; min-width: 0; }
.xp-top { display: flex; justify-content: space-between; gap: 8px; font-size: 9.5px; font-weight: 800; color: var(--ink-soft); letter-spacing: .04em; margin-bottom: 4px; }
.xp-top b { color: var(--ink); }
.xp-track { height: 8px; background: #efe4d3; border-radius: 99px; overflow: hidden; box-shadow: inset 0 1px 2px rgba(52,37,78,.12); }
.xp-fill {
  height: 100%; border-radius: inherit;
  background: linear-gradient(90deg, #8a6bf2, #ff9d5c, #ffd45e);
  background-size: 200% 100%;
  animation: xpShimmer 3s linear infinite;
  transition: width .6s cubic-bezier(.2,.8,.2,1);
}
@keyframes xpShimmer { to { background-position: 200% 0; } }

.primary-actions { display: flex; gap: 8px; margin-left: auto; }
.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 7px;
  border-radius: 13px; border: 1.5px solid transparent;
  font-size: 13px; font-weight: 900; letter-spacing: -.01em;
  padding: 10px 14px; white-space: nowrap;
  transition: transform .12s, box-shadow .12s, filter .12s;
}
.btn:hover { transform: translateY(-1px); }
.btn:active { transform: translateY(1px); }
.btn-primary {
  background: #2b2440; color: #fff9ec;
  border-color: #2b2440; box-shadow: 0 4px 0 #120d22, 0 10px 20px -10px rgba(43,36,64,.6);
}
.btn-primary:hover { background: #3a3157; }
.btn-collect {
  background: linear-gradient(145deg, #ffd86b, #ffb52e);
  color: #4b2c00; border-color: #d99312;
  box-shadow: 0 4px 0 #d99312;
}
.btn-collect:hover { filter: brightness(1.04); }
.btn-collect.active { background: linear-gradient(145deg, #9df0bf, #4ad687); border-color: #1f9d63; box-shadow: 0 4px 0 #1f9d63; color: #094b2c; }
.btn-advance {
  background: linear-gradient(145deg, #8f75f5, #7054d8);
  color: white; border-color: #5a40bd;
  box-shadow: 0 4px 0 #5a40bd;
}
.btn-soft {
  background: var(--paper); border-color: var(--line); color: var(--ink);
  box-shadow: 0 3px 0 #e5d8c6;
}
.btn-soft:hover { background: #fffaf1; }
.btn-danger { background: #e5484f; border-color: #c52f37; color: #fff; box-shadow: 0 4px 0 #b3272f; }
.btn-sm { padding: 7px 11px; font-size: 12px; border-radius: 10px; }
.btn[disabled] { opacity: .45; pointer-events: none; }
.link-btn {
  border: 0; background: none; padding: 0; color: var(--violet);
  font-weight: 900; font-size: inherit; text-decoration: underline; text-underline-offset: 3px;
}

/* ============ banners ============ */
#banner-slot { display: flex; flex-direction: column; gap: 8px; }
.notice {
  display: flex; align-items: center; gap: 12px;
  margin-top: 14px; padding: 11px 14px;
  border-radius: 15px; border: 1.5px dashed #d9c7af;
  background: rgba(255, 251, 241, .9);
  font-size: 13px; font-weight: 600; color: var(--ink-soft);
}
.notice b { color: var(--ink); }
.notice .notice-icon { font-size: 20px; }
.notice .notice-actions { margin-left: auto; display: flex; gap: 8px; flex: none; }
.notice-close { border: 0; background: transparent; font-size: 16px; opacity: .6; padding: 4px; }
.collection-banner {
  display: flex; align-items: center; gap: 13px; flex-wrap: wrap;
  margin-top: 14px; padding: 12px 16px;
  border-radius: 16px; border: 2px solid #e0a51b;
  background: linear-gradient(100deg, #fff4c9, #ffe49a);
  box-shadow: 0 8px 24px -16px rgba(180, 120, 0, .7);
  animation: bannerDrop .4s cubic-bezier(.2,.9,.3,1.2);
}
.collection-banner .banner-emoji { font-size: 27px; animation: coinBob 1.6s ease-in-out infinite; }
.collection-banner .banner-copy { font-size: 13px; font-weight: 700; }
.collection-banner .banner-copy strong { display: block; font-size: 15px; font-weight: 900; }
.collection-banner .banner-progress { margin-left: auto; display: flex; align-items: center; gap: 10px; }
.mini-track { width: 110px; height: 9px; border-radius: 99px; background: rgba(255,255,255,.7); overflow: hidden; }
.mini-track span { display: block; height: 100%; border-radius: inherit; background: linear-gradient(90deg, #ffae2b, #ff7a3d); transition: width .5s; }
@keyframes bannerDrop { from { opacity: 0; transform: translateY(-8px); } }
@keyframes coinBob { 0%,100% { transform: translateY(0) rotate(-5deg); } 50% { transform: translateY(-4px) rotate(5deg); } }

/* ============ ledger ============ */
.ledger-head { display: flex; align-items: flex-end; justify-content: space-between; gap: 20px; flex-wrap: wrap; margin-bottom: 18px; }
.ledger-actions { display: flex; gap: 8px; flex-wrap: wrap; }
.ledger-stats { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 12px; margin-bottom: 18px; }
.l-stat {
  position: relative; overflow: hidden;
  background: var(--paper); border: 1.5px solid var(--line); border-radius: 16px;
  padding: 13px 15px; box-shadow: var(--shadow-soft);
}
.l-stat::after {
  content: attr(data-emoji); position: absolute; right: 8px; top: 4px;
  font-size: 30px; opacity: .14; transform: rotate(9deg);
}
.l-stat .l-label { font-size: 9.5px; font-weight: 900; letter-spacing: .1em; text-transform: uppercase; color: var(--ink-soft); }
.l-stat strong { display: block; font-size: 22px; font-weight: 900; letter-spacing: -.03em; margin-top: 5px; font-variant-numeric: tabular-nums; }
.l-stat .l-note { font-size: 10px; font-weight: 700; color: var(--ink-soft); margin-top: 2px; }
.l-stat.green strong { color: var(--green); }
.l-stat.amber strong { color: #b06a00; }
.ledger-panel { background: var(--paper); border: 1.5px solid var(--line); border-radius: 20px; box-shadow: var(--shadow-soft); overflow: hidden; }
.filter-bar { display: flex; align-items: center; gap: 8px; padding: 12px 14px; border-bottom: 1px solid var(--line); flex-wrap: wrap; background: #fffcf6; }
.filter-label { font-size: 10px; font-weight: 900; letter-spacing: .09em; text-transform: uppercase; color: var(--ink-soft); margin-right: 3px; }
.filter-chip {
  border: 1.5px solid var(--line); background: #fff; border-radius: 99px;
  padding: 6px 11px; font-size: 11px; font-weight: 800; color: var(--ink-soft);
  transition: background .14s, color .14s, border-color .14s;
}
.filter-chip:hover { border-color: #bda9f0; color: var(--violet); }
.filter-chip.active { background: var(--violet); border-color: var(--violet); color: #fff; box-shadow: 0 3px 0 #5a40bd; }
.ledger-count { margin-left: auto; font-size: 10px; font-weight: 800; color: var(--ink-soft); }
.table-wrap { overflow-x: auto; }
.ledger-table { width: 100%; border-collapse: collapse; min-width: 880px; }
.ledger-table th {
  text-align: left; padding: 10px 12px; font-size: 9px; font-weight: 900;
  letter-spacing: .1em; text-transform: uppercase; color: var(--ink-soft);
  background: #fffaf1; border-bottom: 1.5px solid var(--line); white-space: nowrap;
}
.ledger-table td { padding: 11px 12px; border-bottom: 1px solid #f1e9dc; font-size: 12px; vertical-align: middle; }
.ledger-table tbody tr:hover { background: #fffdf8; }
.ledger-table tbody tr:last-child td { border-bottom: 0; }
.ledger-table .num { text-align: right; font-variant-numeric: tabular-nums; font-weight: 800; white-space: nowrap; }
.ledger-table .col-month { font-weight: 800; white-space: nowrap; }
.month-cell small { display: block; font-size: 9px; font-weight: 700; color: var(--ink-soft); }
.tenant-cell { display: flex; align-items: center; gap: 8px; min-width: 150px; }
.mini-avatar {
  width: 28px; height: 28px; border-radius: 9px; flex: none;
  display: grid; place-items: center; font-size: 15px;
  background: #fff1c4; border: 1px solid #e3c67d;
}
.tenant-cell b { display: block; font-size: 12px; font-weight: 900; line-height: 1.15; }
.tenant-cell small { display: block; font-size: 9.5px; font-weight: 700; color: var(--ink-soft); }
.building-cell small { display: block; font-size: 9.5px; font-weight: 700; color: var(--ink-soft); }
.building-cell b { font-size: 11.5px; font-weight: 800; }
.math-note { font-size: 10px; font-weight: 700; color: var(--ink-soft); line-height: 1.35; min-width: 170px; }
.math-note b { color: var(--ink); font-weight: 900; }
.math-note .eq { color: var(--violet); font-weight: 900; }
.type-pill {
  display: inline-flex; align-items: center; gap: 4px;
  border-radius: 99px; padding: 3px 7px; font-size: 8.5px; font-weight: 900;
  letter-spacing: .04em; text-transform: uppercase; white-space: nowrap;
  border: 1px solid transparent;
}
.type-pill.payment { background: var(--green-soft); color: var(--green); border-color: #b1e8ca; }
.type-pill.partial { background: var(--amber-soft); color: #9c6100; border-color: #f2d693; }
.type-pill.rollover { background: #efe9ff; color: var(--violet); border-color: #d5c8ff; }
.type-pill.charge { background: #e9f2ff; color: #2f6fb3; border-color: #c3dcf8; }
.type-pill.adjust { background: #f1ece4; color: #7a6a53; border-color: #e1d5c2; }
.balance-clear { color: var(--green); }
.balance-owed { color: var(--red); }
.balance-credit { color: #2f6fb3; }
.ledger-empty { padding: 46px 20px; text-align: center; color: var(--ink-soft); font-size: 13px; font-weight: 600; }
.ledger-empty span { display: block; font-size: 38px; margin-bottom: 8px; opacity: .7; }

/* ============ modals ============ */
body.modal-open { overflow: hidden; }
.modal-backdrop {
  position: fixed; inset: 0; z-index: 100;
  display: flex; align-items: center; justify-content: center;
  padding: 22px;
  background: rgba(37, 29, 58, .55);
  backdrop-filter: blur(5px);
  animation: fadeIn .18s ease-out;
}
.modal {
  width: min(520px, 100%); max-height: calc(100vh - 44px); overflow-y: auto;
  background: var(--paper);
  border: 2px solid #2b2440; border-radius: 22px;
  box-shadow: 0 10px 0 rgba(20, 14, 34, .35), 0 30px 70px -20px rgba(0,0,0,.5);
  animation: modalPop .28s cubic-bezier(.2,.9,.3,1.22);
  position: relative;
}
.modal.wide { width: min(700px, 100%); }
@keyframes fadeIn { from { opacity: 0; } }
@keyframes modalPop { from { opacity: 0; transform: translateY(18px) scale(.96); } }
.modal-head {
  display: flex; align-items: flex-start; gap: 12px;
  padding: 19px 20px 13px; border-bottom: 1.5px solid var(--line);
  position: sticky; top: 0; z-index: 5; background: var(--paper);
}
.modal-head .modal-icon {
  width: 42px; height: 42px; border-radius: 13px; flex: none;
  display: grid; place-items: center; font-size: 22px;
  background: #fff0c2; border: 1.5px solid #e8c45c;
}
.modal-title { font-size: 20px; font-weight: 900; letter-spacing: -.03em; line-height: 1.1; }
.modal-sub { font-size: 11.5px; font-weight: 600; color: var(--ink-soft); margin-top: 3px; }
.modal-close {
  margin-left: auto; width: 32px; height: 32px; border-radius: 9px; flex: none;
  border: 1.5px solid var(--line); background: #fff; font-size: 15px; line-height: 1;
}
.modal-close:hover { background: #fff5e5; }
.modal-body { padding: 18px 20px; }
.modal-foot {
  display: flex; align-items: center; gap: 8px; flex-wrap: wrap;
  padding: 14px 20px 18px; border-top: 1.5px solid var(--line);
  position: sticky; bottom: 0; background: var(--paper);
}
.modal-foot .spacer { flex: 1; }
.form-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 13px; }
.form-grid .span-2 { grid-column: 1 / -1; }
.field { display: flex; flex-direction: column; gap: 5px; }
.field > label { font-size: 10px; font-weight: 900; letter-spacing: .08em; text-transform: uppercase; color: var(--ink-soft); }
.field input, .field select {
  width: 100%; border: 1.5px solid #d9cbb8; border-radius: 11px;
  background: #fffefb; padding: 10px 11px; font-size: 14px; font-weight: 700;
  transition: border-color .14s, box-shadow .14s;
}
.field input:focus, .field select:focus { border-color: var(--violet); box-shadow: 0 0 0 3px rgba(116,85,214,.16); outline: none; }
.field input[type="number"] { font-variant-numeric: tabular-nums; }
.field .field-hint { font-size: 9.5px; font-weight: 600; color: var(--ink-soft); line-height: 1.3; }
.emoji-picker { display: flex; gap: 5px; flex-wrap: wrap; }
.emoji-opt input { position: absolute; opacity: 0; width: 1px; height: 1px; }
.emoji-opt span {
  display: grid; place-items: center; width: 39px; height: 39px;
  border: 1.5px solid #e1d5c3; border-radius: 11px; background: #fff;
  font-size: 21px; cursor: pointer; transition: transform .12s, border-color .12s, background .12s;
}
.emoji-opt span:hover { transform: translateY(-2px); }
.emoji-opt input:checked + span { border-color: #7455d6; background: #f1ebff; box-shadow: 0 0 0 2px rgba(116,85,214,.2); }
.emoji-opt input:focus-visible + span { outline: 3px solid #7455d6; outline-offset: 2px; }
.calc-box {
  background: linear-gradient(160deg, #fff9e9, #fff4d6);
  border: 1.5px solid #e8d5a5; border-radius: 14px; padding: 12px 14px;
}
.calc-box .calc-title { font-size: 9.5px; font-weight: 900; letter-spacing: .09em; text-transform: uppercase; color: #96700d; margin-bottom: 7px; }
.calc-row { display: flex; justify-content: space-between; gap: 12px; font-size: 11.5px; font-weight: 700; padding: 3px 0; color: #6b5b35; }
.calc-row b { font-variant-numeric: tabular-nums; font-weight: 900; color: #3f341c; }
.calc-row.total { border-top: 1.5px dashed #dcc38a; margin-top: 5px; padding-top: 7px; font-size: 13px; }
.calc-row.total b { font-size: 17px; }
.calc-row.total.clear b { color: var(--green); }
.calc-row.total.owed b { color: var(--red); }
.calc-row.total.credit b { color: #2f6fb3; }
.quick-pay { display: flex; gap: 6px; flex-wrap: wrap; margin-top: 8px; }
.quick-pay button {
  border: 1.5px solid #d9cbb8; background: #fff; border-radius: 9px;
  padding: 5px 9px; font-size: 10px; font-weight: 900; color: var(--ink-soft);
}
.quick-pay button:hover { border-color: var(--violet); color: var(--violet); }
.tenant-summary-card { display: flex; align-items: center; gap: 11px; padding: 11px 12px; border: 1.5px solid var(--line); border-radius: 13px; background: #fffaf2; margin-bottom: 14px; }
.tenant-summary-card .avatar { width: 42px; height: 42px; font-size: 23px; }
.tenant-summary-card b { display: block; font-size: 14px; font-weight: 900; }
.tenant-summary-card small { display: block; font-size: 10.5px; font-weight: 700; color: var(--ink-soft); }
.status-line { display: flex; align-items: center; gap: 6px; flex-wrap: wrap; margin-top: 4px; }
.status-dot { width: 8px; height: 8px; border-radius: 50%; display: inline-block; }
.status-dot.clear { background: #35b86b; }
.status-dot.partial { background: #f2bb26; }
.status-dot.overdue { background: #e5454d; }
.tiny-pill { font-size: 9px; font-weight: 900; letter-spacing: .04em; border-radius: 99px; padding: 2px 6px; background: #f1ece4; color: #6b5b45; }
.danger-zone { border-top: 1.5px dashed var(--line); margin-top: 15px; padding-top: 13px; display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
.danger-zone p { flex: 1; font-size: 10.5px; color: var(--ink-soft); font-weight: 600; }
.color-picker { display: flex; gap: 7px; flex-wrap: wrap; }
.color-opt input { position: absolute; opacity: 0; width: 1px; height: 1px; }
.color-opt span {
  display: block; width: 34px; height: 34px; border-radius: 10px;
  border: 2.5px solid #fff; box-shadow: 0 0 0 1.5px #d9cbb8; cursor: pointer;
  transition: transform .12s, box-shadow .12s;
}
.color-opt span:hover { transform: translateY(-2px); }
.color-opt input:checked + span { box-shadow: 0 0 0 2.5px #2b2440; transform: scale(1.04); }
.settings-list { display: flex; flex-direction: column; gap: 8px; }
.settings-row { display: flex; align-items: center; gap: 11px; padding: 11px 12px; border: 1.5px solid var(--line); border-radius: 12px; background: #fffdf8; }
.settings-row .sr-icon { font-size: 20px; width: 27px; text-align: center; }
.settings-row .sr-copy { flex: 1; }
.settings-row b { display: block; font-size: 12px; font-weight: 900; }
.settings-row small { display: block; font-size: 10px; font-weight: 600; color: var(--ink-soft); }
.switch { position: relative; width: 42px; height: 24px; flex: none; }
.switch input { opacity: 0; width: 0; height: 0; }
.switch span { position: absolute; inset: 0; background: #d9cbb8; border-radius: 99px; transition: background .2s; cursor: pointer; }
.switch span::after { content: ""; position: absolute; width: 18px; height: 18px; border-radius: 50%; background: #fff; top: 3px; left: 3px; transition: transform .2s; box-shadow: 0 1px 3px rgba(0,0,0,.2); }
.switch input:checked + span { background: #35b86b; }
.switch input:checked + span::after { transform: translateX(18px); }
.file-input { display: none; }

/* ============ toasts / fx ============ */
.toasts { position: fixed; right: 20px; bottom: 20px; z-index: 200; display: flex; flex-direction: column; gap: 8px; pointer-events: none; max-width: 340px; }
.toast {
  display: flex; align-items: center; gap: 10px;
  background: #2b2440; color: #fffaf0;
  border-radius: 13px; padding: 10px 14px;
  font-size: 12px; font-weight: 700; line-height: 1.3;
  box-shadow: 0 12px 28px -10px rgba(0,0,0,.5);
  animation: toastIn .3s cubic-bezier(.2,.9,.3,1.2);
  border: 1.5px solid rgba(255,255,255,.12);
}
.toast.out { animation: toastOut .3s ease forwards; }
.toast .toast-icon { font-size: 19px; flex: none; }
.toast.gold { background: linear-gradient(140deg, #3a2d12, #64450e); border-color: #e0a51b; }
.toast.green { background: linear-gradient(140deg, #103d29, #1c6b48); border-color: #4ad687; }
.toast.rose { background: linear-gradient(140deg, #4a1b22, #752d36); border-color: #ff8f8a; }
@keyframes toastIn { from { opacity: 0; transform: translateX(24px) scale(.96); } }
@keyframes toastOut { to { opacity: 0; transform: translateX(24px) scale(.96); } }
#fx { position: fixed; inset: 0; z-index: 180; pointer-events: none; overflow: hidden; }
.fx-coin {
  position: fixed; font-size: 22px; z-index: 181; pointer-events: none;
  animation: coinFly 1s cubic-bezier(.1,.7,.3,1) forwards;
  filter: drop-shadow(0 2px 2px rgba(0,0,0,.25));
}
@keyframes coinFly {
  0% { opacity: 1; transform: translate(0,0) scale(.7) rotate(0); }
  30% { opacity: 1; transform: translate(calc(var(--dx) * .3), calc(var(--dy) * .3 - 60px)) scale(1.15) rotate(80deg); }
  100% { opacity: 0; transform: translate(var(--dx), var(--dy)) scale(.65) rotate(320deg); }
}
.fx-plus {
  position: fixed; z-index: 182; pointer-events: none;
  font-size: 20px; font-weight: 900; color: #fff;
  text-shadow: 0 2px 0 #1f9d63, 0 0 12px rgba(35, 160, 100, .7);
  animation: plusFloat 1.2s ease-out forwards;
  font-variant-numeric: tabular-nums;
}
@keyframes plusFloat { 0% { opacity: 0; transform: translate(-50%, 0) scale(.7); } 20% { opacity: 1; transform: translate(-50%, -10px) scale(1.1); } 100% { opacity: 0; transform: translate(-50%, -64px) scale(1); } }
.confetti-piece {
  position: fixed; top: -20px; z-index: 181; width: 9px; height: 14px; border-radius: 2px;
  animation: confettiFall var(--dur, 2.4s) linear forwards;
  opacity: .95;
}
@keyframes confettiFall {
  to { transform: translate(var(--drift, 30px), 110vh) rotate(720deg); opacity: .6; }
}
.month-pop-fx {
  position: fixed; left: 50%; top: 42%; z-index: 182; transform: translate(-50%, -50%);
  font-size: 72px; animation: monthPop 1.4s ease forwards; pointer-events: none;
  filter: drop-shadow(0 8px 20px rgba(60, 40, 100, .4));
}
@keyframes monthPop { 0% { opacity: 0; transform: translate(-50%,-50%) scale(.4) rotate(-15deg); } 30% { opacity: 1; transform: translate(-50%,-50%) scale(1.1) rotate(4deg); } 70% { opacity: 1; } 100% { opacity: 0; transform: translate(-50%,-60%) scale(1.2); } }

/* ============ footer ============ */
.footer {
  display: flex; align-items: center; justify-content: center; gap: 7px; flex-wrap: wrap;
  padding: 26px 8px 4px; font-size: 10.5px; font-weight: 700; color: var(--ink-soft);
}
.footer-dot { opacity: .5; }
#save-state.saving { color: var(--amber); }
#save-state.saved { color: var(--green); }

/* ============ empty states ============ */
.empty-hero {
  position: relative; z-index: 2; grid-column: 1 / -1;
  background: rgba(255,253,248,.78); border: 2.5px dashed #b9a98f; border-radius: 22px;
  padding: 50px 26px; text-align: center;
}
.empty-hero .empty-emoji { font-size: 60px; display: block; margin-bottom: 10px; }
.empty-hero h3 { font-size: 24px; font-weight: 900; letter-spacing: -.03em; }
.empty-hero p { font-size: 13px; font-weight: 600; color: var(--ink-soft); margin: 6px auto 16px; max-width: 420px; }

/* ============ responsive ============ */
@media (max-width: 1180px) {
  .controlbar { flex-wrap: wrap; }
  .xp-wrap { order: 5; max-width: none; flex-basis: 100%; }
  .primary-actions { order: 4; }
  .building-layout { grid-template-columns: minmax(0, 1fr) 300px; }
}
@media (max-width: 1020px) {
  .topbar { flex-wrap: wrap; gap: 12px 18px; }
  .dashboard { order: 3; flex-basis: 100%; justify-content: flex-start; }
  .top-actions { margin-left: auto; }
  .building-layout { grid-template-columns: 1fr; }
  .roster { position: static; }
  .roster-list { max-height: 330px; }
  .b-summary { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@media (max-width: 820px) {
  .app-shell { padding: 0 16px 26px; }
  .map-hero { align-items: flex-start; flex-direction: column; gap: 14px; }
  .hero-actions { width: 100%; }
  .ledger-stats { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .neighborhood { padding: 20px 14px 46px; border-radius: 22px; }
  .buildings-grid { grid-template-columns: 1fr; }
  .bcard-sky { height: 195px; }
  .page-title { font-size: 30px; }
  .collection-banner .banner-progress { margin-left: 0; width: 100%; }
  .collection-banner .banner-progress .mini-track { flex: 1; }
}
@media (max-width: 700px) {
  .topbar { padding: 14px 2px 10px; }
  .brand-copy h1 { font-size: 21px; }
  .brand-copy p { font-size: 9.5px; }
  .brand-mark { width: 46px; height: 46px; border-radius: 14px; }
  .brand-house { font-size: 26px; }
  .dashboard { gap: 7px; }
  .dash-stat { flex: 1; min-width: 0; padding: 8px 10px; gap: 7px; border-radius: 13px; }
  .dash-stat .dash-icon { width: 28px; height: 28px; font-size: 15px; border-radius: 9px; }
  .dash-stat .dash-label { font-size: 8.5px; letter-spacing: .04em; }
  .dash-stat strong { font-size: 15.5px; }
  .controlbar { position: static; gap: 9px; padding: 9px; }
  .tabs { order: 1; }
  .tab { padding: 7px 9px; font-size: 11.5px; }
  .month-chip { order: 2; margin-left: auto; font-size: 12.5px; }
  .month-chip small { font-size: 8px; }
  .primary-actions { order: 3; width: 100%; margin: 0; }
  .primary-actions .btn { flex: 1; font-size: 11.5px; padding: 10px 8px; }
  .primary-actions .collect-btn span, .primary-actions .advance-btn span { white-space: nowrap; }
  .xp-wrap { order: 4; }
  .xp-top { font-size: 8.5px; }
  main { padding-top: 16px; }
  .building-actions { width: 100%; }
  .building-actions .btn { flex: 1; }
  .building-actions .btn span { font-size: 11px; }
  .b-stat strong { font-size: 19px; }
  .floors { padding: 10px 9px 6px; gap: 6px; }
  .floor-tag { width: 20px; font-size: 8px; }
  .floor-units { gap: 5px; padding: 5px; }
  .unit { padding: 5px; min-height: 116px; }
  .unit-window { height: 38px; }
  .unit-window .t-emoji { font-size: 19px; }
  .unit-name { font-size: 9px; }
  .unit-balance { font-size: 8.5px; }
  .unit-rent { display: none; }
  .unit-window .coin-btn { width: 34px; height: 34px; }
  .cutaway-sign { font-size: 10px; padding: 3px 9px; }
  .ledger-table { min-width: 0; }
  .ledger-table thead { display: none; }
  .ledger-table tbody { display: flex; flex-direction: column; }
  .ledger-table tbody tr {
    display: grid; grid-template-columns: 1fr 1fr; gap: 5px 12px;
    padding: 11px 13px; border-bottom: 1.5px solid var(--line);
    background: #fffdf8;
  }
  .ledger-table td { display: flex; justify-content: space-between; align-items: baseline; gap: 8px; padding: 1px 0; border: 0; font-size: 11px; }
  .ledger-table td::before { content: attr(data-label); font-size: 8px; font-weight: 900; letter-spacing: .08em; text-transform: uppercase; color: var(--ink-soft); }
  .ledger-table td.col-tenant, .ledger-table td.col-math { grid-column: 1 / -1; }
  .ledger-table td.col-tenant::before, .ledger-table td.col-math::before { display: none; }
  .ledger-table td.col-tenant { border-bottom: 1px dashed #eee2d0; padding-bottom: 5px; }
  .ledger-table td.col-math { padding-top: 2px; }
  .tenant-cell { min-width: 0; }
  .math-note { min-width: 0; }
  .ledger-table .num { justify-content: space-between; }
  .ledger-count { width: 100%; margin-left: 0; padding-top: 2px; }
  .filter-bar { padding: 10px; gap: 6px; }
  .ledger-stats { gap: 8px; }
  .l-stat { padding: 10px 12px; }
  .l-stat strong { font-size: 18px; }
  .modal-backdrop { padding: 10px; align-items: flex-end; }
  .modal { max-height: 92vh; border-radius: 20px; }
  .modal-head { padding: 15px 15px 11px; }
  .modal-body { padding: 14px 15px; }
  .modal-foot { padding: 12px 15px 15px; }
  .form-grid { grid-template-columns: 1fr; gap: 11px; }
  .toasts { left: 12px; right: 12px; bottom: 12px; max-width: none; }
  .notice { align-items: flex-start; font-size: 11.5px; }
  .notice .notice-actions { flex-direction: column; }
}
@media (max-width: 430px) {
  .brand { min-width: 0; }
  .brand-copy p { display: none; }
  .dashboard { flex-wrap: nowrap; }
  .dash-stat { padding: 7px 8px; }
  .dash-stat .dash-icon { display: none; }
  .dash-stat strong { font-size: 14px; }
  .dash-stat.occupied { display: none; }
  .primary-actions .collect-btn span { display: none; }
  .primary-actions .collect-btn::after { content: "Collect"; }
  .building-name { font-size: 26px; }
  .b-summary { grid-template-columns: 1fr 1fr; gap: 8px; }
  .b-stat { padding: 9px 10px; }
  .b-stat strong { font-size: 17px; }
  .floor-units { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .page-title { font-size: 27px; }
  .footer { font-size: 9.5px; }
}
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: .001ms !important; animation-iteration-count: 1 !important; transition-duration: .001ms !important; }
}

content.text:
  .footer { font-size: 9.5px; }
