864:   t.paidThisMonth = roundMoney(t.paidThisMonth + amount);
865:   t.due = roundMoney(t.due - amount);
866:   const full = t.due <= .004;
867:   const type = full ? 'payment' : 'partial';
868:   addLedgerEntry(t, type, amount, note || (t.due < -.004 ? `Overpayment · ${money(-t.due)} credit carried` : full ? 'Paid in full' : `${money(t.due)} remains due`));
869:   const earned = xpFor(amount) + (before > .004 && full ? 5 : 0);
