845: function exportCSV() {
846:   const headers = ['Month', 'Date', 'Building', 'Tenant', 'Apartment', 'Activity', 'Rent', 'Previous due', 'Amount', 'Balance after', 'Note'];
847:   const rows = state.ledger.slice().sort((a, b) => a.ts - b.ts).map((e) => [e.monthLabel || e.monthKey, new Date(e.ts).toISOString(), e.buildingName, e.tenantName, e.unit, e.type, e.rent, e.prevDue, e.amount, e.dueAfter, e.note]);
848:   downloadFile('property-tycoon-ledger.csv', [headers, ...rows].map((r) => r.map(csvCell).join(',')).join('\r\n'), 'text/csv;charset=utf-8');
