855: function addLedgerEntry(t, type, amount, note = '') {
856:   const b = getBuilding(t.buildingId);
857:   state.ledger.push({ id: uid('led'), ts: Date.now(), monthKey: monthKey(state.month), monthLabel: monthLabel(state.month),
858:     buildingId: t.buildingId, buildingName: b?.name || '', tenantId: t.id, tenantName: t.name, unit: t.unit,
859:     type, rent: t.rent, prevDue: t.prevDue, amount: roundMoney(amount), dueAfter: t.due, note });
860: }
861: function logPayment(tenantId, amount, note = '') {
862:   const t = getTenant(tenantId); if (!t || !Number.isFinite(amount) || amount <= 0) return false;
863:   const before = t.due;
864:   t.paidThisMonth = roundMoney(t.paidThisMonth + amount);
865:   t.due = roundMoney(t.due - amount);
866:   const full = t.due <= .004;
867:   const type = full ? 'payment' : 'partial';
868:   addLedgerEntry(t, type, amount, note || (t.due < -.004 ? `Overpayment · ${money(-t.due)} credit carried` : full ? 'Paid in full' : `${money(t.due)} remains due`));
869:   const earned = xpFor(amount) + (before > .004 && full ? 5 : 0);
870:   const beforeLevel = levelInfo().level;
871:   state.xp += earned;
872:   AudioKit.coin();
873:   if (before > .004 && full) { AudioKit.register(); fxConfetti(18); }
874:   if (levelInfo().level > beforeLevel) { AudioKit.level(); toast(`Level ${levelInfo().level}! ${levelInfo().title}`, { icon: '⭐' }); }
875:   return true;
876: }
877: function advanceMonth() {
878:   const from = monthLabel(state.month);
879:   state.month = addMonths(state.month, 1);
880:   state.tenants.forEach((t, i) => {
881:     const carried = t.due;
882:     t.prevDue = carried;
883:     t.due = roundMoney(t.rent + carried);
884:     t.paidThisMonth = 0;
885:     addLedgerEntry(t, 'rollover', 0, `New month · rent ${money(t.rent)} + carried ${money(carried)} = ${money(t.due)}`);
886:   });
887:   ui.collecting = false;
888:   AudioKit.advance(); fxMonth();
889:   toast(`Welcome to ${monthLabel(state.month)}! Rent and balances rolled forward.`, { icon: '📅', duration: 4800 });
890:   commit();
891: }
