747:     .slice().sort((a, b) => b.ts - a.ts);
748:   const months = [...new Set(filtered.map((e) => e.monthKey))];
749:   const rows = filtered.map((e) => {
750:     const kind = e.type === 'payment' || e.type === 'partial' ? 'Payment' : e.type === 'charge' ? 'Rent charge' : 'Month rollover';
751:     const cls = e.type === 'payment' ? 'paid' : e.type === 'partial' ? 'partial' : 'charge';
752:     const amount = e.type === 'payment' || e.type === 'partial' ? `− ${money(e.amount)}` : e.type === 'charge' ? money(e.rent) : '—';
753:     const balance = e.dueAfter < -.004 ? `${money(-e.dueAfter)} credit` : money(Math.max(0, e.dueAfter));
754:     return `<tr><td><b>${esc(e.monthLabel || e.monthKey || '')}</b><small>${formatDate(e.ts)} · ${formatTime(e.ts)}</small></td>
755:       <td><span class="ledger-tenant">${esc(e.tenantName || 'Former tenant')}<small>${esc(e.unit ? `Apt ${e.unit}` : '')}</small></span></td>
756:       <td>${esc(e.buildingName || getBuilding(e.buildingId)?.name || 'Removed building')}</td>
757:       <td><span class="ledger-kind ${cls}">${kind}</span><small>${esc(e.note || '')}</small></td>
758:       <td class="money-cell ${e.type === 'payment' || e.type === 'partial' ? 'positive' : ''}">${amount}</td>
759:       <td class="money-cell"><b>${balance}</b></td></tr>`;
760:   }).join('');
761:   const monthOptions = months.map((key) => {
762:     const label = filtered.find((e) => e.monthKey === key)?.monthLabel || key;
763:     return `<option value="${esc(key)}">${esc(label)}</option>`;
764:   }).join('');
765:   return `<section class="ledger-page">
766:     <div class="ledger-hero"><div><p class="page-kicker">The books · ${filtered.length} entries</p><h2 class="page-title">Ledger & history 📒</h2><p class="page-sub">Every rent charge, rollover, and payment in one place. Balances are shown after each entry.</p></div>
