function ledgerView() {
  const filtered = state.ledger.filter((e) => ui.ledgerBuildingId === 'all' || e.buildingId === ui.ledgerBuildingId)
    .slice().sort((a, b) => b.ts - a.ts);
  const months = [...new Set(filtered.map((e) => e.monthKey))];
  const rows = filtered.map((e) => {
    const kind = e.type === 'payment' || e.type === 'partial' ? 'Payment' : e.type === 'charge' ? 'Rent charge' : 'Month rollover';
    const cls = e.type === 'payment' ? 'paid' : e.type === 'partial' ? 'partial' : 'charge';
    const amount = e.type === 'payment' || e.type === 'partial' ? `− ${money(e.amount)}` : e.type === 'charge' ? money(e.rent) : '—';
    const balance = e.dueAfter < -.004 ? `${money(-e.dueAfter)} credit` : money(Math.max(0, e.dueAfter));
    return `<tr><td><b>${esc(e.monthLabel || e.monthKey || '')}</b><small>${formatDate(e.ts)} · ${formatTime(e.ts)}</small></td>
      <td><span class="ledger-tenant">${esc(e.tenantName || 'Former tenant')}<small>${esc(e.unit ? `Apt ${e.unit}` : '')}</small></span></td>
      <td>${esc(e.buildingName || getBuilding(e.buildingId)?.name || 'Removed building')}</td>
      <td><span class="ledger-kind ${cls}">${kind}</span><small>${esc(e.note || '')}</small></td>
      <td class="money-cell ${e.type === 'payment' || e.type === 'partial' ? 'positive' : ''}">${amount}</td>
      <td class="money-cell"><b>${balance}</b></td></tr>`;
  }).join('');
  const monthOptions = months.map((key) => {
    const label = filtered.find((e) => e.monthKey === key)?.monthLabel || key;
    return `<option value="${esc(key)}">${esc(label)}</option>`;
  }).join('');
  return `<section class="ledger-page">
    <div class="ledger-hero"><div><p class="page-kicker">The books · ${filtered.length} entries</p><h2 class="page-title">Ledger & history 📒</h2><p class="page-sub">Every rent charge, rollover, and payment in one place. Balances are shown after each entry.</p></div>
      <button class="btn btn-soft" data-action="export-csv">⬇ Export CSV</button></div>
    <div class="ledger-tools"><label>Property <select id="ledger-building-filter"><option value="all">All buildings</option>${state.buildings.map((b) => `<option value="${b.id}" ${ui.ledgerBuildingId === b.id ? 'selected' : ''}>${esc(b.name)}</option>`).join('')}</select></label>
      <label>Month <select id="ledger-month-filter"><option value="all">All months</option>${monthOptions}</select></label>
      <span class="ledger-total">${money(filtered.filter((e) => e.type === 'payment' || e.type === 'partial').reduce((s, e) => s + e.amount, 0))} payments recorded</span></div>
    <div class="ledger-table-wrap"><table class="ledger-table"><thead><tr><th>Month / date</th><th>Tenant</th><th>Building</th><th>Activity</th><th>Amount</th><th>Balance after</th></tr></thead>
      <tbody>${rows || `<tr><td colspan="6"><div class="ledger-empty"><span>🧾</span><b>No ledger entries yet</b><small>Rent charges and payments will appear here as you manage your buildings.</small></div></td></tr>`}</tbody></table></div>
    <p class="ledger-footnote">Balances on each row are the tenant’s running balance immediately after that activity. A negative balance is a carried credit.</p>
  </section>`;
}

